export class Order {
  readonly #lines: Line[] = [];

  private constructor(readonly id: OrderId, readonly customerId: CustomerId) {}

  static open(customerId: CustomerId): Order {
    return new Order(nextOrderId(), customerId);
  }

  addLine(line: Line): void {
    if (this.total().plus(line.price).greaterThan(LIMIT)) throw new OrderLimitExceeded();
    this.#lines.push(line);
  }
}
